package com.thang.nihongo_user.service;
import com.thang.nihongo_user.model.*;import com.thang.nihongo_user.repository.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.core.type.TypeReference;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class ClassroomService {
 private final ClassroomRepository classes;private final ClassroomMemberRepository members;private final ClassroomAssignmentRepository assignments;private final ExamAttemptRepository attempts;private final ExamFeedbackRepository feedback;
 private final ICourseRepository courses;private final IUserSubscriptionRepository subscriptions;private final ClassroomContentClient content;private final ClassroomUserClient directory;private final ObjectMapper json;private final org.springframework.jdbc.core.JdbcTemplate jdbc;
 private final StudyActivityService activity;
 public record ClassInput(@NotBlank @Size(max=200) String name,@Size(max=1000) String description,Long courseId){}
 public record AssignmentInput(@NotBlank @Size(max=200) String title,@NotNull @Positive Long templateId,@NotBlank @Pattern(regexp="EXAM|HOMEWORK") String kind,@Min(0) @Max(180) int minutes,@NotNull LocalDateTime startsAt,@NotNull LocalDateTime dueAt){}
 public record AssignmentView(Long id,Long classroomId,String title,String kind,int minutes,LocalDateTime startsAt,LocalDateTime dueAt,boolean published,long version){}
 public record Answers(Map<Long,String> answers,long version){}
 public record FeedbackInput(Long questionId,@NotBlank @Size(max=2000) String text){}
 public record QuestionView(Long id,String content,String answerA,String answerB,String answerC,String answerD,String chosen,String correctAnswer){}
 public record AttemptView(Long id,Long assignmentId,String title,long version,long serverNow,long endsAt,boolean finished,int correct,int total,double score,List<QuestionView> questions,boolean answersVisible){}
 public Page<Classroom> list(String actor,boolean admin,int page){return admin?classes.findAllByOrderByCreatedAtDescIdDesc(page(page)):classes.findByOwnerOrderByCreatedAtDescIdDesc(actor,page(page));}
 @Transactional public Classroom create(String actor,ClassInput input){if(input.courseId()!=null&&!courses.existsById(input.courseId()))throw missing();var c=new Classroom();c.setOwner(actor);c.setName(input.name().trim());c.setDescription(input.description());c.setCourseId(input.courseId());c.setCreatedAt(LocalDateTime.now());return classes.save(c);}
 @Transactional public Classroom archive(String actor,boolean admin,Long id,boolean archived,long version){var c=classes.lock(id).orElseThrow(ClassroomService::missing);owner(c,actor,admin);if(c.getVersion()!=version)throw conflict("Lớp đã được cập nhật");c.setArchived(archived);return c;}
 public Page<ClassroomMember> members(String actor,boolean admin,Long id,int page){own(id,actor,admin);return members.findByClassroomIdOrderByJoinedAtAscIdAsc(id,page(page));}
 // Directory lookup is remote: it runs before the classroom row lock and DB transaction.
 private org.springframework.transaction.support.TransactionOperations transactions=org.springframework.transaction.support.TransactionOperations.withoutTransaction();
 @org.springframework.beans.factory.annotation.Autowired(required=false) void setTransactionManager(org.springframework.transaction.PlatformTransactionManager manager){transactions=new org.springframework.transaction.support.TransactionTemplate(manager);}
 @Transactional(propagation=org.springframework.transaction.annotation.Propagation.NOT_SUPPORTED) public void addMembers(String actor,boolean admin,Long id,List<String> userIds){if(own(id,actor,admin).isArchived())throw conflict("Lớp đã lưu trữ");if(userIds==null||userIds.isEmpty()||userIds.size()>100||userIds.stream().anyMatch(u->u==null||u.length()!=36))throw bad("Chọn 1–100 học viên");var ids=userIds.stream().distinct().toList();var valid=directory.learners(ids);if(valid.size()!=ids.size()||!new HashSet<>(valid.stream().map(ClassroomUserClient.Learner::userId).toList()).containsAll(ids))throw bad("Có học viên không tồn tại hoặc không hoạt động");
  transactions.executeWithoutResult(status->{var c=classes.lock(id).orElseThrow(ClassroomService::missing);owner(c,actor,admin);if(c.isArchived())throw conflict("Lớp đã lưu trữ");if(c.getCourseId()!=null&&!new HashSet<>(subscriptions.activeMembers(c.getCourseId(),ids)).containsAll(ids))throw bad("Học viên cần đăng ký khóa học còn hiệu lực");var existing=new HashSet<>(members.findByClassroomIdAndUserIdIn(id,ids).stream().map(ClassroomMember::getUserId).toList());var added=ids.stream().filter(u->!existing.contains(u)).toList();if(members.countByClassroomId(id)+added.size()>1000)throw bad("Một lớp tối đa 1000 học viên");jdbc.batchUpdate("insert into classroom_member (classroom_id,user_id,joined_at) values (?,?,?)",added,100,(statement,userId)->{statement.setLong(1,id);statement.setString(2,userId);statement.setTimestamp(3,java.sql.Timestamp.valueOf(LocalDateTime.now()));});});}
 @Transactional public void removeMember(String actor,boolean admin,Long id,String userId){var c=classes.lock(id).orElseThrow(ClassroomService::missing);owner(c,actor,admin);members.lock(id,userId).ifPresent(members::delete);}
 // The exam template is fetched over HTTP outside a DB transaction; the single insert commits on its own.
 @Transactional(propagation=org.springframework.transaction.annotation.Propagation.NOT_SUPPORTED) public AssignmentView assign(String actor,boolean admin,Long classroomId,AssignmentInput input){var c=own(classroomId,actor,admin);if(c.isArchived())throw conflict("Lớp đã lưu trữ");if(!List.of("EXAM","HOMEWORK").contains(input.kind())||!input.dueAt().isAfter(input.startsAt())||!input.dueAt().isAfter(LocalDateTime.now())||input.kind().equals("EXAM")&&input.minutes()<1)throw bad("Loại đề, thời lượng hoặc thời gian không hợp lệ");var exam=content.exam(input.templateId());if(exam==null||exam.questions()==null||exam.questions().isEmpty()||exam.questions().size()>100||exam.questions().stream().anyMatch(q->q.id()==null||q.levelId()==null||q.correctAnswer()==null||!q.correctAnswer().matches("[ABCD]")))throw bad("Đề thi chưa hợp lệ");if(c.getCourseId()!=null){var course=courses.findById(c.getCourseId()).orElseThrow(ClassroomService::missing);if(exam.questions().stream().anyMatch(q->!course.getLevelId().equals(q.levelId())))throw bad("Đề cần cùng cấp độ với khóa học của lớp");}var a=new ClassroomAssignment();a.setClassroomId(classroomId);a.setTemplateId(input.templateId());a.setTitle(input.title().trim());a.setKind(input.kind());a.setMinutes(input.kind().equals("HOMEWORK")?0:input.minutes());a.setStartsAt(input.startsAt());a.setDueAt(input.dueAt());a.setCreatedAt(LocalDateTime.now());a.setSnapshot(write(exam.questions()));return view(assignments.save(a));}
 @Transactional public AssignmentView publish(String actor,boolean admin,Long id,long version){var a=assignments.findById(id).orElseThrow(ClassroomService::missing);var c=classes.lock(a.getClassroomId()).orElseThrow(ClassroomService::missing);owner(c,actor,admin);if(c.isArchived()||a.getVersion()!=version||!a.getDueAt().isAfter(LocalDateTime.now()))throw conflict("Lớp/đề đã thay đổi hoặc quá hạn");if(members.countByClassroomId(c.getId())==0)throw bad("Thêm học viên trước khi giao đề");a.setPublished(true);return view(a);}
 public Page<AssignmentView> assignments(String actor,boolean admin,Long id,int page){own(id,actor,admin);return assignments.findByClassroomIdOrderByCreatedAtDescIdDesc(id,page(page)).map(this::view);}
 public Page<AssignmentView> mine(String userId,int page){return assignments.mine(userId,page(page)).map(this::view);}
 @Transactional public AttemptView start(String userId,Long assignmentId){var old=attempts.findByAssignmentIdAndUserId(assignmentId,userId).orElse(null);if(old!=null)return read(userId,old.getId());var a=assignments.findById(assignmentId).orElseThrow(ClassroomService::missing);var c=classes.findById(a.getClassroomId()).orElseThrow(ClassroomService::missing);members.lock(c.getId(),userId).orElseThrow(()->denied("Bạn chưa thuộc lớp này"));old=attempts.findByAssignmentIdAndUserId(assignmentId,userId).orElse(null);if(old!=null)return attempt(old,a,false);var now=LocalDateTime.now();if(!a.isPublished()||c.isArchived()||now.isBefore(a.getStartsAt())||!now.isBefore(a.getDueAt()))throw conflict("Đề chưa mở hoặc đã hết hạn");var levels=questions(a).stream().map(ClassroomContentClient.Question::levelId).distinct().toList();if(!new HashSet<>(subscriptions.accessibleLevels(userId,levels)).containsAll(levels))throw denied("Bạn cần quyền học còn hiệu lực cho các cấp độ trong đề");var e=new ExamAttempt();e.setUserId(userId);e.setAssignmentId(a.getId());e.setStartedAt(now);e.setEndsAt(a.getMinutes()>0&&now.plusMinutes(a.getMinutes()).isBefore(a.getDueAt())?now.plusMinutes(a.getMinutes()):a.getDueAt());e.setTotal(questions(a).size());return attempt(attempts.saveAndFlush(e),a,false);}
 @Transactional public AttemptView read(String userId,Long id){var e=attempts.lock(id).orElseThrow(ClassroomService::missing);if(!e.getUserId().equals(userId))throw denied("Bài làm không thuộc tài khoản");var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);finishIfExpired(e,a);return attempt(e,a,false);}
 @Transactional public AttemptView save(String userId,Long id,Answers input,boolean submit){var e=attempts.lock(id).orElseThrow(ClassroomService::missing);if(!e.getUserId().equals(userId))throw denied("Bài làm không thuộc tài khoản");var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);finishIfExpired(e,a);if(e.getSubmittedAt()!=null)return attempt(e,a,false);if(input==null||input.version()!=e.getVersion())throw conflict("Bài làm có cập nhật mới, hãy tải lại");var values=input.answers();if(values==null||values.size()>100)throw bad("Đáp án không hợp lệ");Set<Long> ids=new HashSet<>(questions(a).stream().map(ClassroomContentClient.Question::id).toList());if(!ids.containsAll(values.keySet())||values.values().stream().anyMatch(v->v==null||!v.matches("[ABCD]")))throw bad("Đáp án/câu hỏi không thuộc đề");e.setAnswers(write(values));if(!values.isEmpty())activity.record(userId,"exam:"+e.getId(),LocalDate.now());if(submit)finish(e,a,LocalDateTime.now());attempts.saveAndFlush(e);return attempt(e,a,false);}
 public Page<ExamAttempt> results(String actor,boolean admin,Long assignmentId,int page){var a=assignments.findById(assignmentId).orElseThrow(ClassroomService::missing);own(a.getClassroomId(),actor,admin);return attempts.findByAssignmentIdOrderByStartedAtDescIdDesc(assignmentId,page(page));}
 @Transactional public AttemptView inspect(String actor,boolean admin,Long id){var e=attempts.lock(id).orElseThrow(ClassroomService::missing);var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);own(a.getClassroomId(),actor,admin);finishIfExpired(e,a);return attempt(e,a,true);}
 @Transactional public ExamFeedback comment(String actor,boolean admin,Long id,FeedbackInput input){var e=attempts.findById(id).orElseThrow(ClassroomService::missing);var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);own(a.getClassroomId(),actor,admin);if(e.getSubmittedAt()==null)throw conflict("Chỉ nhận xét bài đã nộp");if(input.questionId()!=null&&questions(a).stream().noneMatch(q->q.id().equals(input.questionId())))throw bad("Câu hỏi không thuộc đề");var f=new ExamFeedback();f.setAttemptId(id);f.setActor(actor);f.setQuestionId(input.questionId());f.setText(input.text().trim());f.setCreatedAt(LocalDateTime.now());return feedback.save(f);}
 public Page<ExamFeedback> feedback(String userId,boolean teacher,boolean admin,Long id,int page){var e=attempts.findById(id).orElseThrow(ClassroomService::missing);if(teacher){var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);own(a.getClassroomId(),userId,admin);}else if(!e.getUserId().equals(userId))throw denied("Bài làm không thuộc tài khoản");return feedback.findByAttemptIdOrderByCreatedAtAscIdAsc(id,page(page));}
 @Transactional public void finalizeDeadline(Long id){var e=attempts.lock(id).orElse(null);if(e!=null&&e.getSubmittedAt()==null){var a=assignments.findById(e.getAssignmentId()).orElseThrow(ClassroomService::missing);finishIfExpired(e,a);}}
 private void finishIfExpired(ExamAttempt e,ClassroomAssignment a){if(e.getSubmittedAt()==null&&!e.getEndsAt().isAfter(LocalDateTime.now()))finish(e,a,e.getEndsAt());}
 private void finish(ExamAttempt e,ClassroomAssignment a,LocalDateTime at){var selected=answers(e);var items=questions(a);int correct=(int)items.stream().filter(q->q.correctAnswer().equals(selected.get(q.id()))).count();e.setCorrect(correct);e.setTotal(items.size());e.setScore(Math.round(correct*10000.0/items.size())/100.0);e.setSubmittedAt(at);}
 private AttemptView attempt(ExamAttempt e,ClassroomAssignment a,boolean teacher){boolean visible=teacher||e.getSubmittedAt()!=null&&(a.getKind().equals("HOMEWORK")||!LocalDateTime.now().isBefore(a.getDueAt()));var values=answers(e);return new AttemptView(e.getId(),a.getId(),a.getTitle(),e.getVersion(),System.currentTimeMillis(),e.getEndsAt().atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),e.getSubmittedAt()!=null,e.getCorrect(),e.getTotal(),e.getScore(),questions(a).stream().map(q->new QuestionView(q.id(),q.content(),q.answerA(),q.answerB(),q.answerC(),q.answerD(),values.get(q.id()),visible?q.correctAnswer():null)).toList(),visible);}
 private Map<Long,String> answers(ExamAttempt e){try{return json.readValue(e.getAnswers(),new TypeReference<Map<Long,String>>(){});}catch(Exception error){throw new IllegalStateException("Không đọc được bài làm");}}
 // A published snapshot never changes; parse it once instead of several times per request.
 private final com.github.benmanes.caffeine.cache.Cache<String,List<ClassroomContentClient.Question>> parsedSnapshots=com.github.benmanes.caffeine.cache.Caffeine.newBuilder().maximumSize(500).expireAfterAccess(java.time.Duration.ofMinutes(30)).build();
 private List<ClassroomContentClient.Question> questions(ClassroomAssignment a){String snapshot=a.getSnapshot();return parsedSnapshots.get(a.getId()+":"+snapshot.length()+":"+snapshot.hashCode(),ignored->{try{return List.copyOf(json.readValue(snapshot,new TypeReference<List<ClassroomContentClient.Question>>(){}));}catch(Exception error){throw new IllegalStateException("Không đọc được bản đề");}});}
 private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception error){throw new IllegalStateException("Không lưu được dữ liệu đề thi");}}
 private AssignmentView view(ClassroomAssignment a){return new AssignmentView(a.getId(),a.getClassroomId(),a.getTitle(),a.getKind(),a.getMinutes(),a.getStartsAt(),a.getDueAt(),a.isPublished(),a.getVersion());}
 private Classroom own(Long id,String actor,boolean admin){var c=classes.findById(id).orElseThrow(ClassroomService::missing);owner(c,actor,admin);return c;}private void owner(Classroom c,String actor,boolean admin){if(!admin&&!c.getOwner().equals(actor))throw denied("Chỉ người phụ trách lớp được thao tác");}
 private Pageable page(int page){if(page<0)throw bad("Trang không hợp lệ");return PageRequest.of(page,20);}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}private static ResponseStatusException conflict(String text){return new ResponseStatusException(HttpStatus.CONFLICT,text);}private static ResponseStatusException denied(String text){return new ResponseStatusException(HttpStatus.FORBIDDEN,text);}private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Không tìm thấy lớp/đề/bài làm");}
}
